import { z, ZodError, ZodType } from "zod";
import { callLLM, LLMError } from "./client";

export class JsonGuardError extends Error {
  readonly raw: string;
  readonly cause?: unknown;
  constructor(message: string, raw: string, cause?: unknown) {
    super(message);
    this.name = "JsonGuardError";
    this.raw = raw;
    this.cause = cause;
  }
}

export function extractJson(raw: string): unknown {
  const trimmed = raw.trim();
  const direct = tryParse(trimmed);
  if (direct.ok) return direct.value;

  const start = trimmed.indexOf("{");
  if (start === -1) {
    throw new JsonGuardError("No '{' found in LLM response", raw);
  }

  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = start; i < trimmed.length; i++) {
    const ch = trimmed[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (ch === "\\") {
      escape = true;
      continue;
    }
    if (ch === '"') {
      inString = !inString;
      continue;
    }
    if (inString) continue;
    if (ch === "{") depth++;
    else if (ch === "}") {
      depth--;
      if (depth === 0) {
        const slice = trimmed.slice(start, i + 1);
        const parsed = tryParse(slice);
        if (parsed.ok) return parsed.value;
        throw new JsonGuardError(
          `Failed to parse balanced JSON block: ${parsed.error}`,
          raw,
          parsed.error,
        );
      }
    }
  }

  throw new JsonGuardError("Unbalanced JSON object in LLM response", raw);
}

function tryParse(text: string):
  | { ok: true; value: unknown }
  | { ok: false; error: string } {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (err) {
    return { ok: false, error: (err as Error).message };
  }
}

export type ValidateOptions = {
  system: string;
  user: string;
  model?: string;
  temperature?: number;
};

export async function validateOrRepair<T extends ZodType>(
  schema: T,
  initialRaw: string,
  opts: ValidateOptions,
): Promise<{ value: z.infer<T>; usedRepair: boolean; raw: string }> {
  const first = tryValidate(schema, initialRaw);
  if (first.ok) {
    return { value: first.value, usedRepair: false, raw: initialRaw };
  }

  const repairPrompt = buildRepairPrompt(initialRaw, first.error);
  let repaired: string;
  try {
    const r = await callLLM({
      system: REPAIR_SYSTEM,
      user: repairPrompt,
      model: opts.model,
      temperature: 0,
      jsonMode: true,
    });
    repaired = r.raw;
  } catch (err) {
    throw new JsonGuardError(
      `Validation failed and LLM repair call errored: ${(err as LLMError).message}`,
      initialRaw,
      err,
    );
  }

  const second = tryValidate(schema, repaired);
  if (second.ok) {
    return { value: second.value, usedRepair: true, raw: repaired };
  }

  throw new JsonGuardError(
    `Validation failed twice. First: ${first.error}. After repair: ${second.error}`,
    repaired,
  );
}

function tryValidate<T extends ZodType>(
  schema: T,
  raw: string,
):
  | { ok: true; value: z.infer<T> }
  | { ok: false; error: string } {
  let parsed: unknown;
  try {
    parsed = extractJson(raw);
  } catch (err) {
    return { ok: false, error: (err as Error).message };
  }
  const result = schema.safeParse(parsed);
  if (result.success) {
    return { ok: true, value: result.data };
  }
  return { ok: false, error: formatZodError(result.error) };
}

function formatZodError(err: ZodError): string {
  return err.issues
    .slice(0, 5)
    .map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`)
    .join("; ");
}

const REPAIR_SYSTEM = `You fix malformed JSON. Return ONLY a single corrected JSON object. No prose, no markdown fences.`;

function buildRepairPrompt(badJson: string, reason: string): string {
  return `The following JSON failed validation: ${reason}

Original JSON:
${badJson.slice(0, 8000)}

Return ONLY the corrected JSON object that fixes the issues. Do not change semantically valid fields. Add any missing required fields with sensible defaults. Return JSON only.`;
}

