import { beforeEach, describe, expect, it, vi } from "vitest";
import { z } from "zod";

const callLLMMock = vi.fn();

vi.mock("@/lib/llm/client", async () => {
  const actual =
    await vi.importActual<typeof import("@/lib/llm/client")>(
      "@/lib/llm/client",
    );
  return {
    ...actual,
    callLLM: callLLMMock,
  };
});

const { extractJson, JsonGuardError, validateOrRepair } = await import(
  "@/lib/llm/jsonGuard"
);

describe("extractJson", () => {
  it("parses a clean JSON object", () => {
    expect(extractJson('{"a": 1, "b": "x"}')).toEqual({ a: 1, b: "x" });
  });

  it("extracts JSON surrounded by prose", () => {
    const raw = "Sure thing! Here is the JSON:\n{\"k\": 42}\nThanks!";
    expect(extractJson(raw)).toEqual({ k: 42 });
  });

  it("handles nested objects and strings containing braces", () => {
    const raw = `prefix { "a": { "b": "}{" }, "c": [1,2,3] } trailing`;
    expect(extractJson(raw)).toEqual({ a: { b: "}{" }, c: [1, 2, 3] });
  });

  it("handles strings with escaped quotes", () => {
    const raw = `{"msg": "he said \\"hi\\""}`;
    expect(extractJson(raw)).toEqual({ msg: 'he said "hi"' });
  });

  it("throws when no '{' is found", () => {
    expect(() => extractJson("no json here")).toThrow(JsonGuardError);
  });

  it("throws when braces are unbalanced", () => {
    expect(() => extractJson('{"a": 1 ')).toThrow(JsonGuardError);
  });

  it("throws when block parses to invalid JSON", () => {
    expect(() => extractJson("{not, json}")).toThrow(JsonGuardError);
  });
});

describe("validateOrRepair", () => {
  const schema = z.object({
    name: z.string(),
    age: z.number().int().nonnegative(),
  });

  beforeEach(() => {
    callLLMMock.mockReset();
  });

  it("returns immediately when first response is valid (no LLM call)", async () => {
    const raw = '{"name":"alice","age":30}';
    const result = await validateOrRepair(schema, raw, {
      system: "ignored",
      user: "ignored",
    });
    expect(result.usedRepair).toBe(false);
    expect(result.value).toEqual({ name: "alice", age: 30 });
    expect(callLLMMock).not.toHaveBeenCalled();
  });

  it("invokes repair once when schema fails, repair returns valid", async () => {
    const broken = '{"name":"bob","age":"not-a-number"}';
    callLLMMock.mockResolvedValueOnce({
      raw: '{"name":"bob","age":99}',
      model: "mock",
      promptTokens: 0,
      completionTokens: 10,
    });

    const result = await validateOrRepair(schema, broken, {
      system: "ignored",
      user: "ignored",
    });

    expect(callLLMMock).toHaveBeenCalledTimes(1);
    expect(result.usedRepair).toBe(true);
    expect(result.value).toEqual({ name: "bob", age: 99 });
  });

  it("throws JsonGuardError when both attempts fail validation", async () => {
    const broken = '{"name":"carol","age":"still-bad"}';
    callLLMMock.mockResolvedValueOnce({
      raw: '{"name":"carol","age":"also-bad"}',
      model: "mock",
      promptTokens: 0,
      completionTokens: 10,
    });

    await expect(
      validateOrRepair(schema, broken, {
        system: "ignored",
        user: "ignored",
      }),
    ).rejects.toBeInstanceOf(JsonGuardError);

    expect(callLLMMock).toHaveBeenCalledTimes(1);
  });

  it("does not retry beyond one repair attempt", async () => {
    const broken = '{"name":"dan","age":"x"}';
    callLLMMock.mockResolvedValue({
      raw: '{"name":"dan","age":"y"}',
      model: "mock",
      promptTokens: 0,
      completionTokens: 5,
    });

    await expect(
      validateOrRepair(schema, broken, {
        system: "ignored",
        user: "ignored",
      }),
    ).rejects.toBeInstanceOf(JsonGuardError);

    expect(callLLMMock).toHaveBeenCalledTimes(1);
  });
});
